// BarnraiseServiceHandler is an implementation of the barnraise.v1.BarnraiseService service.
type BarnraiseServiceHandler interface {
	// Projects
	ListProjects(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.ProjectsResponse], error)
	RegisterProject(context.Context, *connect.Request[v1.RegisterProjectRequest]) (*connect.Response[v1.ProjectsResponse], error)
	ReloadProject(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.ProjectsResponse], error)
	// Items
	CreateItem(context.Context, *connect.Request[v1.CreateItemRequest]) (*connect.Response[v1.CreateItemResponse], error)
	GetItem(context.Context, *connect.Request[v1.ItemRef]) (*connect.Response[v1.ItemResponse], error)
	ListItems(context.Context, *connect.Request[v1.ListItemsRequest]) (*connect.Response[v1.ItemsResponse], error)
	UpdateItem(context.Context, *connect.Request[v1.UpdateItemRequest]) (*connect.Response[v1.ItemResponse], error)
	CloseItem(context.Context, *connect.Request[v1.CloseItemRequest]) (*connect.Response[v1.ItemResponse], error)
	NextItem(context.Context, *connect.Request[v1.NextItemRequest]) (*connect.Response[v1.Assignment], error)
	Deliver(context.Context, *connect.Request[v1.DeliverRequest]) (*connect.Response[v1.ItemResponse], error)
	SubmitReview(context.Context, *connect.Request[v1.ReviewRequest]) (*connect.Response[v1.ItemResponse], error)
	ReportCheck(context.Context, *connect.Request[v1.ReportCheckRequest]) (*connect.Response[v1.ItemResponse], error)
	Timeline(context.Context, *connect.Request[v1.ItemRef]) (*connect.Response[v1.TimelineResponse], error)
	Estimate(context.Context, *connect.Request[v1.ItemRef]) (*connect.Response[v1.EstimateResponse], error)
	Takeover(context.Context, *connect.Request[v1.ItemRef]) (*connect.Response[v1.TakeoverResponse], error)
	Handback(context.Context, *connect.Request[v1.HandbackRequest]) (*connect.Response[v1.ItemResponse], error)
	Redo(context.Context, *connect.Request[v1.RedoRequest]) (*connect.Response[v1.ItemResponse], error)
	// Proposals and tweaks
	Propose(context.Context, *connect.Request[v1.ProposeRequest]) (*connect.Response[v1.ProposeResponse], error)
	ListProposals(context.Context, *connect.Request[v1.ListProposalsRequest]) (*connect.Response[v1.ListProposalsResponse], error)
	DecideProposal(context.Context, *connect.Request[v1.DecideProposalRequest]) (*connect.Response[v1.ProposalResponse], error)
	AddTweak(context.Context, *connect.Request[v1.AddTweakRequest]) (*connect.Response[v1.AddTweakResponse], error)
	// Owner
	AskOwner(context.Context, *connect.Request[v1.AskOwnerRequest]) (*connect.Response[v1.QuestionResponse], error)
	ListQuestions(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.QuestionsResponse], error)
	Answer(context.Context, *connect.Request[v1.AnswerRequest]) (*connect.Response[v1.QuestionResponse], error)
	Approve(context.Context, *connect.Request[v1.ApproveRequest]) (*connect.Response[v1.Empty], error)
	// Discuss sends the owner's message about a question or an item to the
	// advisor, a read-only agent with the strongest model, and returns the
	// conversation with its answer. It runs only when the owner writes, in
	// standby too.
	Discuss(context.Context, *connect.Request[v1.DiscussRequest]) (*connect.Response[v1.DiscussionResponse], error)
	// ListParts describes the parts of a project (its areas with their own
	// barnraise.yaml) and how their work goes.
	ListParts(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.PartsResponse], error)
	GetDiscussion(context.Context, *connect.Request[v1.DiscussionRef]) (*connect.Response[v1.DiscussionResponse], error)
	// Delegate lets the advisor decide a question or a proposal in the
	// owner's place and applies the answer it suggests.
	Delegate(context.Context, *connect.Request[v1.DiscussionRef]) (*connect.Response[v1.DiscussionResponse], error)
	// TriageProposals asks the advisor for a decision on every open proposal;
	// nothing is applied.
	TriageProposals(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.ProposalTriageResponse], error)
	SetGoal(context.Context, *connect.Request[v1.SetGoalRequest]) (*connect.Response[v1.SetGoalResponse], error)
	SetFocus(context.Context, *connect.Request[v1.FocusRequest]) (*connect.Response[v1.FocusResponse], error)
	ClearFocus(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.Empty], error)
	Pause(context.Context, *connect.Request[v1.PauseRequest]) (*connect.Response[v1.Empty], error)
	Resume(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.Empty], error)
	// Views
	Status(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.StatusResponse], error)
	// The whole cluster in one answer: what each item is doing, on which
	// machine, with which worktrees, processes, pull request and cost. It is
	// answered from memory, whatever the size of the history.
	Overview(context.Context, *connect.Request[v1.OverviewRequest]) (*connect.Response[v1.OverviewResponse], error)
	Metrics(context.Context, *connect.Request[v1.MetricsRequest]) (*connect.Response[v1.MetricsResponse], error)
	Digest(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.DigestResponse], error)
	Queue(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.QueueResponse], error)
	ProcessQueue(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.QueueResponse], error)
	ListEvents(context.Context, *connect.Request[v1.EventsRequest]) (*connect.Response[v1.EventsResponse], error)
	// Messaging
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest]) (*connect.Response[v1.MessageResponse], error)
	Inbox(context.Context, *connect.Request[v1.InboxRequest]) (*connect.Response[v1.InboxResponse], error)
	Journal(context.Context, *connect.Request[v1.JournalRequest]) (*connect.Response[v1.Empty], error)
	ReportViolation(context.Context, *connect.Request[v1.PolicyViolationRequest]) (*connect.Response[v1.Empty], error)
	// Knowledge
	Context(context.Context, *connect.Request[v1.ContextRequest]) (*connect.Response[v1.ContextResponse], error)
	Find(context.Context, *connect.Request[v1.FindRequest]) (*connect.Response[v1.FindResponse], error)
	Get(context.Context, *connect.Request[v1.KnowledgeRequest]) (*connect.Response[v1.KnowledgeResponse], error)
	Related(context.Context, *connect.Request[v1.KnowledgeRequest]) (*connect.Response[v1.KnowledgeResponse], error)
	Why(context.Context, *connect.Request[v1.KnowledgeRequest]) (*connect.Response[v1.KnowledgeResponse], error)
	History(context.Context, *connect.Request[v1.KnowledgeRequest]) (*connect.Response[v1.KnowledgeResponse], error)
	Rules(context.Context, *connect.Request[v1.KnowledgeRequest]) (*connect.Response[v1.KnowledgeResponse], error)
	Revalidate(context.Context, *connect.Request[v1.RevalidateRequest]) (*connect.Response[v1.RevalidateResponse], error)
	Sweep(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.RevalidateResponse], error)
	// Accounts and machines
	UpsertAccount(context.Context, *connect.Request[v1.AccountRequest]) (*connect.Response[v1.AccountResponse], error)
	ListAccounts(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.AccountsResponse], error)
	// StartAccountLogin starts the provider's login of one account on the
	// machines named, all at the same time. Each machine keeps its own login;
	// no credential travels between machines.
	StartAccountLogin(context.Context, *connect.Request[v1.AccountLoginRequest]) (*connect.Response[v1.AccountLoginResponse], error)
	// GetAccountLogin tells how the login goes on each machine.
	GetAccountLogin(context.Context, *connect.Request[v1.AccountLoginRequest]) (*connect.Response[v1.AccountLoginResponse], error)
	// AnswerAccountLogin hands a machine's login the code its page showed.
	AnswerAccountLogin(context.Context, *connect.Request[v1.AccountLoginRequest]) (*connect.Response[v1.AccountLoginResponse], error)
	// CancelAccountLogin stops the logins that still run.
	CancelAccountLogin(context.Context, *connect.Request[v1.AccountLoginRequest]) (*connect.Response[v1.AccountLoginResponse], error)
	ReportUsage(context.Context, *connect.Request[v1.ReportUsageRequest]) (*connect.Response[v1.Empty], error)
	ListMachines(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.MachinesResponse], error)
	// Recent readings of the machines (CPU, memory, temperature, GPU), kept in
	// memory by each daemon for charts. Never stored.
	MachineHistory(context.Context, *connect.Request[v1.MachineHistoryRequest]) (*connect.Response[v1.MachineHistoryResponse], error)
	LeaveMachine(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.LeaveResponse], error)
	// The other machines of the cluster, as this daemon sees them.
	ListPeers(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.PeersResponse], error)
	// Asks other machines to stop their daemon, as `barnraise down` does there.
	StopPeers(context.Context, *connect.Request[v1.StopPeersRequest]) (*connect.Response[v1.StopPeersResponse], error)
	// Standby is the machine's own switch: in standby its daemon keeps
	// answering (status, panel, events between machines) and starts no agent,
	// check or merge. It is kept in the machine's configuration, so the daemon
	// starts the way it stopped.
	SetStandby(context.Context, *connect.Request[v1.StandbyRequest]) (*connect.Response[v1.StandbyResponse], error)
	// What is active on each machine, what falls back and why, and how to fix
	// it (ADR-0046). Owner and admin tokens only.
	Capabilities(context.Context, *connect.Request[v1.CapabilitiesRequest]) (*connect.Response[v1.CapabilitiesResponse], error)
	// Installs (or removes) the optional tools Barnraise ships recipes for,
	// without root, on this machine and the named ones.
	InstallTools(context.Context, *connect.Request[v1.InstallToolsRequest]) (*connect.Response[v1.InstallToolsResponse], error)
	// Tokens and audit
	CreateToken(context.Context, *connect.Request[v1.CreateTokenRequest]) (*connect.Response[v1.CreateTokenResponse], error)
	ListTokens(context.Context, *connect.Request[v1.Empty]) (*connect.Response[v1.TokensResponse], error)
	RevokeToken(context.Context, *connect.Request[v1.RevokeTokenRequest]) (*connect.Response[v1.Empty], error)
	ListAudit(context.Context, *connect.Request[v1.AuditRequest]) (*connect.Response[v1.AuditResponse], error)
}

